-- ═══ 2. CHECK constraints ════════════════════════════════════════════════════

-- 2FA is mandatory for every role (D-032): an active admin must be enrolled.
ALTER TABLE "admin_user" ADD CONSTRAINT "admin_user_mfa_required_check"
  CHECK (NOT "is_active" OR ("mfa_enabled_at" IS NOT NULL AND "mfa_secret_encrypted" IS NOT NULL AND "mfa_key_version" IS NOT NULL));
-- An encrypted secret always records the key version that encrypted it (D-065).
ALTER TABLE "admin_user" ADD CONSTRAINT "admin_user_mfa_key_check"
  CHECK (("mfa_secret_encrypted" IS NULL) = ("mfa_key_version" IS NULL));
ALTER TABLE "admin_user" ADD CONSTRAINT "admin_user_mfa_last_used_step_check"
  CHECK ("mfa_last_used_step" IS NULL OR "mfa_last_used_step" >= 0);

-- Invites: only a 32-byte SHA-256 hash of the token is stored (D-070).
ALTER TABLE "admin_invite" ADD CONSTRAINT "admin_invite_token_hash_check"
  CHECK (octet_length("token_hash") = 32);
ALTER TABLE "admin_invite" ADD CONSTRAINT "admin_invite_expiry_check"
  CHECK ("expires_at" > "created_at");
ALTER TABLE "admin_invite" ADD CONSTRAINT "admin_invite_outcome_check"
  CHECK ("accepted_at" IS NULL OR "revoked_at" IS NULL);
ALTER TABLE "admin_invite" ADD CONSTRAINT "admin_invite_pending_mfa_check"
  CHECK (("pending_mfa_secret_encrypted" IS NULL) = ("pending_mfa_key_version" IS NULL));

-- Recovery codes: only 32-byte SHA-256 hashes are stored (D-071).
ALTER TABLE "admin_recovery_code" ADD CONSTRAINT "admin_recovery_code_hash_check"
  CHECK (octet_length("code_hash") = 32);
